const day = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric",
  year: "numeric",
  timeZone: "UTC",
});

export function formatDay(value: string) {
  return day.format(new Date(`${value}T00:00:00Z`));
}

